title:
Update the afl.rs bare git repo at /mnt/data1/git/github.com/rust-fuzz/afl.rs.git: 1. Create a worktree from the bare repo at /tmp/aflrs_wt 2. Read the .gitignore — remove any line that ignores Cargo.lock or flake.lock 3. Read Cargo.toml to understand workspace structure (it has members: afl, cargo-afl, cargo-afl-common) 4. Add a minimal flake.nix that builds the default workspace member:
{
  description = "afl.rs";
  inputs = {
    nixpkgs.url = "github:NixOS/nixpkgs/nixos-unstable";
    flake-utils.url = "github:numtide/flake-utils";
  };
  outputs = { self, nixpkgs, flake-utils }:
    flake-utils.lib.eachDefaultSystem (system:
      let
        pkgs = nixpkgs.legacyPackages.${system};
      in {
        packages.default = pkgs.rustPlatform.buildRustPackage {
          pname = "afl";
          version = "0.1.0";
          src = ./.;
          cargoLock.lockFile = ./Cargo.lock;
          doCheck = false;
        };
      });
}
 5. git add all files, commit with message "add flake.nix, track Cargo.lock" 6. git push the bare repo 7. Clean up worktree
